/// Event `create` of `oPDummy`: its actions in order.
pub fn create(g: &mut World, cx: &mut Ctx) -> R<()> {
    // #0 action_inherited()
    g.at("oPDummy/create#0", 0); g.event_inherited(cx)?;
    if g.pending().is_some() { return Ok(()); } create_a1(g, cx)?;
    Ok(())
}

